import{_ as e,o,c as a,a3 as c}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Tenant API v1 — Contracts","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Contracts | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-contracts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Contracts | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-contracts"}]]},"headers":[],"relativePath":"api/tenant-v1-contracts.md","filePath":"api/tenant-v1-contracts.md","lastUpdated":1786894349000}'),n={name:"api/tenant-v1-contracts.md"};function d(s,t,r,i,l,u){return o(),a("div",null,[...t[0]||(t[0]=[c('<h1 id="tenant-api-v1-—-contracts" tabindex="-1">Tenant API v1 — Contracts <a class="header-anchor" href="#tenant-api-v1-—-contracts" aria-label="Permalink to &quot;Tenant API v1 — Contracts&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:contracts</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>contracts.assign</code> (and not superadmin), list/stats/view/update only include contracts where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-contracts-stats" tabindex="-1">GET <code>/contracts/stats</code> <a class="header-anchor" href="#get-contracts-stats" aria-label="Permalink to &quot;GET `/contracts/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort).</p><h2 id="contracts-crud" tabindex="-1">Contracts CRUD <a class="header-anchor" href="#contracts-crud" aria-label="Permalink to &quot;Contracts CRUD&quot;">​</a></h2><h3 id="get-contracts" tabindex="-1">GET <code>/contracts</code> <a class="header-anchor" href="#get-contracts" aria-label="Permalink to &quot;GET `/contracts`&quot;">​</a></h3><p>Query: <code>search</code>, <code>status</code>, <code>opportunity_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_contracts</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>opportunity</code>, <code>quotation</code> (when linked), assignee/creator refs, and <code>latest_note</code>.</p><h3 id="post-contracts" tabindex="-1">POST <code>/contracts</code> <a class="header-anchor" href="#post-contracts" aria-label="Permalink to &quot;POST `/contracts`&quot;">​</a></h3><p>Body: <code>opportunity_id</code> (required), <code>quotation_id</code> (optional — only valid when the <strong>Quotations</strong> module is entitled, the quotation is not soft-deleted, the actor may access the quotation, and the quotation belongs to the same opportunity; see <code>LinkableQuotation</code>), <code>title</code> (required), <code>party_name</code>, <code>start_date</code> (required), <code>end_date</code>, <code>value</code>, <code>currency</code> (3-letter, default <code>USD</code>), <code>notes</code>, <code>assigned_to</code>.</p><h3 id="get-contracts-id" tabindex="-1">GET <code>/contracts/{id}</code> <a class="header-anchor" href="#get-contracts-id" aria-label="Permalink to &quot;GET `/contracts/{id}`&quot;">​</a></h3><p>Includes opportunity, quotation (when linked), assignee, creator, notes, and timeline activities.</p><h3 id="put-contracts-id" tabindex="-1">PUT <code>/contracts/{id}</code> <a class="header-anchor" href="#put-contracts-id" aria-label="Permalink to &quot;PUT `/contracts/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> contracts only. Non-draft contracts return 422 on <code>status</code> (<code>Only draft contracts can be edited.</code>). Assignment after activate uses <code>POST /contracts/{id}/assign</code>. Status changes use <code>POST /contracts/{id}/status</code>.</p><h3 id="delete-contracts-id" tabindex="-1">DELETE <code>/contracts/{id}</code> <a class="header-anchor" href="#delete-contracts-id" aria-label="Permalink to &quot;DELETE `/contracts/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>contracts.delete</code>.</p><h3 id="post-contracts-id-restore" tabindex="-1">POST <code>/contracts/{id}/restore</code> <a class="header-anchor" href="#post-contracts-id-restore" aria-label="Permalink to &quot;POST `/contracts/{id}/restore`&quot;">​</a></h3><p>Permission: <code>contracts.restore</code>.</p><h3 id="delete-contracts-id-force" tabindex="-1">DELETE <code>/contracts/{id}/force</code> <a class="header-anchor" href="#delete-contracts-id-force" aria-label="Permalink to &quot;DELETE `/contracts/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted contract. Permission: <code>contracts.force.delete</code>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-contracts-id-assign" tabindex="-1">POST <code>/contracts/{id}/assign</code> <a class="header-anchor" href="#post-contracts-id-assign" aria-label="Permalink to &quot;POST `/contracts/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>contracts.assign</code>.</p><h3 id="post-contracts-id-status" tabindex="-1">POST <code>/contracts/{id}/status</code> <a class="header-anchor" href="#post-contracts-id-status" aria-label="Permalink to &quot;POST `/contracts/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;draft&quot;|&quot;active&quot;|&quot;expired&quot;|&quot;terminated&quot; }</code></p><p>Permission: <code>contracts.update</code>. Rejects disallowed transitions (including re-entering the same status) with a 422 validation error on <code>status</code>. Records a <code>status_changed</code> timeline entry.</p><h3 id="post-contracts-id-notes" tabindex="-1">POST <code>/contracts/{id}/notes</code> <a class="header-anchor" href="#post-contracts-id-notes" aria-label="Permalink to &quot;POST `/contracts/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>contracts.update</code>.</p><h3 id="get-contracts-id-timeline" tabindex="-1">GET <code>/contracts/{id}/timeline</code> <a class="header-anchor" href="#get-contracts-id-timeline" aria-label="Permalink to &quot;GET `/contracts/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>note_added</code>, <code>deleted</code>, <code>restored</code>).</p>',35)])])}const m=e(n,[["render",d]]);export{h as __pageData,m as default};
